INSERT INTO stretchy_report
(report_name, report_type, report_subtype, report_category, report_sql, description, core_report, use_report, self_service_user_report)
VALUES('Loan Outstanding Seguro Obrigatorio', 'Table', NULL, 'Loan', 'SELECT loan_id, transaction_date, type, amount FROM ( SELECT id as loan_id, nr_order, nm_group_charges as type, fecha as transaction_date, amount FROM vw_report_loan_creditnoteoutstandingamount WHERE id IN (${loanIds}) UNION ALL SELECT NULL, 90 AS nr_order, ''--------------------------------------------------------------'', CURRENT_DATE, NULL UNION ALL SELECT id, 100 AS nr_order, ''(=) TOTAL OUTSTANDING'', CURRENT_DATE, SUM(amount) FROM vw_report_loan_creditnoteoutstandingamount WHERE id in (${loanIds}) GROUP BY id ) AS qry ORDER BY nr_order', 'Seguro Obrigatorio Usage', false, true, false);

INSERT INTO stretchy_report_parameter
(report_id, parameter_id, report_parameter_name, mandatory_parameter)
VALUES((SELECT id FROM stretchy_report where report_name = 'Loan Outstanding Seguro Obrigatorio'), 1034, 'loanIds', true);
